// The AI tools. One list: the MCP server advertises it, the API validates against it.
// Kept short on purpose: every word here is sent to the AI at the start of every conversation.
const id = (what: string) => z.string().min(1).max(80).describe(`The ${what} id`);
/** A yes/no that also takes "true"/"false" as text (a chat that loaded an older tool list sends a field it does not know as text). */
const flag = () => z.preprocess((v) => (v === "true" ? true : v === "false" ? false : v), z.boolean()).optional();
/** A number, a list or an object that also takes itself as text (the same: a field an older tool list does not know). */
const num = (n: z.ZodNumber) => z.preprocess((v) => (typeof v === "string" && v.trim() && Number.isFinite(Number(v)) ? Number(v) : v), n).optional();
const asJson = (v: unknown) => { if (typeof v !== "string" || !/^\s*[[{]/.test(v)) return v; try { return JSON.parse(v); } catch { return v; } };
const json = <T extends z.ZodTypeAny>(t: T) => z.preprocess(asJson, t);
const projectId = id("project");
const page = { offset: z.number().int().min(0).optional(), limit: z.number().int().min(1).max(100).optional().describe("Default 20") };
/** Marks are read on one video, or on an edit (its footage and the videos on V1, with where each mark plays). */
const markWhere = { projectId: projectId.optional(), videoId: id("video").optional() };
const markRange = { from: z.number().min(0).optional(), to: z.number().min(0).optional(), edit: z.boolean().optional().describe("from/to are edit seconds (with projectId)") };
const markPage = { offset: z.number().int().min(0).optional(), limit: z.number().int().min(1).max(500).optional().describe("Default 100") };
// The edit list and style rules are described in words, not as full schemas (much shorter); the API checks each
// edit against EditOpSchema and the rules against StyleRulesPatchSchema, and says exactly what is wrong.
/** A stretch of footage to start an edit with: seconds in the original video (default the edit's footage). */
const ShortClip = z.object({ from: z.number().min(0), to: z.number().min(0), videoId: z.string().min(1).max(80).optional() });
const EDIT_FIELDS = `cut_words{wordIds | from,to: removes exactly that range, words or not} restore_words{wordIds (cut, or taken out by a range cut) | from, to: footage seconds a range cut took out, put back} set_captions{on, look: clean|bold|outline (back to that preset), styleId: that style's captions} edit_caption{lineId, text} set_caption_style{look?: start from it, font: ${CAPTION_FONTS.join("|")}, weight, size: % of the frame's short side, color #RRGGBB, highlight: active word colour or null, stroke{color, width % of size} | null, shadow{color, opacity, x, y % of size} | null, box{color, opacity, padding % of size} | null (with a box no stroke), x, y: bottom centre 0-1, wordsAtOnce, wordsPerLine, lines 1-3, case none|upper|lower, tidy} add_text{text (\\n = new line), start, end, preset: title|callout|lower-third|plain, card{color, opacity} full-frame behind, anim none|fade|pop|slide, and any caption style field but highlight and word counts; align left|center|right; x, y: where it hangs; behind: true = behind the person; inside{videoId, from}: a library video plays inside the letters (a track matte; looped; card, stroke, shadow drawn round them), null = none; cutout: true = the letters are cut out of the card, the picture under it shows through} set_text{clipId, same fields} add_zoom{start, end, scale: 1.1 = 110%} add_broll{videoId (a library video, or a Google Drive file's id or link, or a link to a video or picture: brought into the library first), start, end, sourceStart} add_music{trackId: track id or mood | soundId: your own file (add_audio; or url, driveFileId, upload as on set_voice), gainDb} set_voice{soundId: a file from add_audio made from this edit's exported sound (a voice enhanced in Adobe Podcast, a mix) | url: its share link | driveFileId | upload: true = a one-time link your code workspace sends the file to (curl -T; nothing changes until then): it plays in place of every clip's own sound from start (edit seconds, default 0), gainDb; soundId null = the clips' own sound again; set it last (a later cut is not in the file)} add_graphic{graphicId, start, end, params (a template's fields, or a custom graphic's window.params values), from (custom graphics: seconds into it where this placement starts), data: any JSON the graphic reads as window.params.data (a video's word times, a scene list: one graphic for every video), rerecord: true = its recording for these params made again (a bad one is not kept), behind: true = behind the person} behind_person{clipIds: text layers or graphics on V3, off: true = in front again: the person is drawn over them from an AI matte of the footage (people only), as a title behind the speaker; not where the clip under it is framed smaller, moved, keyframed or reversed, nor over b-roll or a transition (the check says where)} apply_style{styleId, overrides: rules; sets the style's captions only, and the result lists its other rules for you to do} set_aspect{aspect: 16:9|9:16|1:1|4:5 (Instagram portrait); footage of another shape is cut to fit: reframe it with set_framing focus "face"} set_rotation{degrees: 0|90|180|270 clockwise, for footage filmed sideways, clipIds?} set_card{clipIds? (default the footage's clips; b-roll ids too: crop, radius, shadow and border over the picture, picture-in-picture), crop{left, top, right, bottom: shares cut from each side, in place}, radius: rounded corners as a share of the card's short side (0.5 = round ends), shadow{color, opacity 0-1, blur, x, y: shares of the frame's short side; {} = a soft shadow} | null, border{color, width: share of the short side} | null, reset: V1 clips drawn as cards; with set_framing (scale under 1, x, y) to shrink and place them} set_background{color #RRGGBB | gradient{from, to, angle: degrees as CSS, 180 = top to bottom} | videoId: a library video, looped | blur: 1-100, the clip's own picture blurred | pattern{kind: grid|dots|paper, color: paper, ink: lines/dots, size: share of the short side} | none: true = black: what shows behind V1 for the whole edit (where it is framed smaller, cropped, rounded, keyed, masked or has its background removed)} set_framing{focus: where the fit cuts footage of another shape (reframing, like Premiere's Auto Reframe): "face" = Rendrr keeps the speaker's face (the one talking) in each clip in view, measured over the clip | {x, y}: that point of the footage (0-1 from the top left) kept in view | null = the middle; scale: 1 = fills the frame, x, y: offset as a share of width/height, 0.3 = 30% down, clipIds? | fitFaceTo: {x, y: where the face goes, 0-1 from the top left; r: half the face height as a share of the frame height, 0.15 = a close-up}: Rendrr finds the face in each clip and works out scale and offset} rename{name} add_media{videoIds: library videos to keep in the project bin (the editor's Media panel) to use later} remove_media{videoIds} set_reference{videoId: a library video (kind reference) shown in the editor's Reference monitor, for you to copy | styleId | null: none; never applied to the edit} split_clip{track, clipId, at} trim_clip{track, clipId, start, end} delete_clip{clipId, track (optional: found from the id)} set_link{track, clipId, linked: false = a V1 clip and its sound (A1) are trimmed apart, true = together again} set_clips{track, clips: [{start, end, label?, id? (keep an id to keep that clip), videoId? (v1), framing? (v1: {scale, x, y} for that clip, null = fill the frame)}]} add_clip{videoId? (default the footage), from, to, index? | at?: edit time, splits the clip there} move_clip{clipId, index | at} set_audio_offset{clipId, start: -0.5 = its sound starts 0.5s early (J cut), end: 0.5 = runs 0.5s into the next clip (L cut), muted} roll_edit{clipId, by: moves the cut after it} slip_clip{clipId, by: same place, later footage} slide_clip{clipId, by: same footage, later in the edit} set_audio{cleanup: a voice preset like Premiere's Essential Sound: none|light|balanced|podcast|voice|noisy (clean up noisy dialogue)|roomy (dry up a roomy voice)|warm|bright|soft (soften a harsh voice)|punchy (loud and punchy, social)|radio (radio announcer)|phone (phone call), loudness: LUFS (default -14) or null = off, peak: dBTP ceiling (default -1), duck: dB music goes down under speech (default 12, 0 = off), fadeIn, fadeOut: whole mix; highpass Hz, denoise dB, presence dB (3.5 kHz lift), deess 0-1, compress ratio: hand values over the preset, null = the preset's; declick: seconds each cut's sound fades out and in (0-0.03, default 0.02), crossfade: seconds (0-0.5, e.g. 0.06) of equal-power crossfade at every dialogue cut instead, from the footage past each cut (nothing moves)} set_clip_audio{track: v1 (dialogue, default)|a2|a3, clipId, gainDb, fadeIn, fadeOut (a music fade not set stays automatic), pan -1 (left)..1 (right), eq{low (120 Hz shelf), mid (1 kHz), high (6 kHz shelf): dB -20..20, bands: up to 4 parametric bells [{f Hz, gain dB, q (1 musical, 4+ narrow)}] (the list replaces them; a notch on a hum: f 60, gain -18, q 10)} (merged), reverb{amount 0-100, size 0-100: a 0.3-2.5 s room}, keys: [{t: s from the clip's start, gainDb}] volume keys, straight between (the list replaces them); null removes each} set_speed{clipId (v1), speed 0.1-10, reverse, ramp: [{at: the clip's footage second, speed, ease?: in|out|in-out|[x1,y1,x2,y2] the change to the next point (default linear)}] null = off; sound keeps pitch 0.5-4x, silent outside or reversed; freeze: a freeze frame's length; interp: frames (each frame held, default)|blend (frames mixed)|flow (optical flow: smooth slow motion, as Premiere's) for slow motion} set_flip{clipId | clipIds (V1 clips or b-roll), flip: h (mirror left to right)|v (upside down)|both|none} freeze_frame{clipId, at: its footage second, length s} set_transition{clipId: on the cut before it | clipIds | all: true, type: cut|dissolve|dip-black|dip-white|whip|zoom|slide|morph (Morph Cut: smooths a jump cut in a talking head, the face flowing from one place to the other; 0.2-0.5 s; face-aware: Rendrr finds the face either side and slides and scales the head into place while the room dissolves; face: false = a plain morph)|push|wipe|iris|cross-zoom|film-dissolve|clock|barn-door|diamond|box (Iris Box)|cross (Iris Cross)|blinds (Venetian Blinds)|checker (Checker Wipe)|wedge (Wedge Wipe), duration s (default 0.5, whip 0.3), dir left|right|up|down (whip, slide, push, wipe, barn-door, blinds: left|right = vertical bands)} set_keyframes{track v1|v2 (b-roll)|v3 (text, graphic), clipId, keys: [{t: s from the clip's start, x, y: centre offset as share of width/height, scale, rotation: degrees clockwise, opacity 0-1, ease: linear|in|out|in-out|[x1,y1,x2,y2] to the next key}], [] = none (left out: kept); anchor {x, y}: the point (shares of the clip's frame, 0.5, 0.5 = the middle; null = the middle; text: a point of its text's box, 0,0 top left, null = its alignment point) it turns and scales about; motionBlur 0-100 (50 = a 180° shutter, 0 = off) on the keyed movement (V1, b-roll, graphics, text)} set_grade{clipId|clipIds (V1 or b-roll)|all|video, exposure stops, contrast -100..100, temperature -100 cool..100 warm, tint -100 green..100 magenta, saturation % (100 = as is), highlights, shadows, whites, blacks, vibrance: -100..100 (as Lumetri), wheels{shadows|midtones|highlights: {hue degrees, amount 0-100, luma -100..100}} (each merged; null removes it), hsl: [{hue, range: degrees wide (40), satMin 0-1, hueShift degrees, saturation %, lightness -100..100}] (one colour only: skin 25, sky 210, greens 110; the list replaces them), hueSat: [[hue 0-1, value 0-1 (0.5 = as is)],...] round the hue circle, hueHue: [[hue 0-1, shift 0-1 (0.5 = as is, 0 = -180°, 1 = +180°)],...] turns colours into others (greens toward teal), lumaSat: [[luma 0-1, saturation 0-1 (0.5 = as is)],...] (less colour in the shadows), curves{master|r|g|b: [[in,out],...] 0-1}, lut{id (get_project lists yours) | name: one of yours by name | cube: the .cube file's own text, imported in the same call (any chat can apply a LUT from its workspace this way; for one over about 17 points use add_lut upload), amount 0-1, input: applied first}, null removes a field, reset} copy_grade{from, to|all|video, with: [grade,key,masks,effects,skin]} match_color{clipIds, to: reference clip; the server measures both} set_key{clipId..., color #RRGGBB taken from the frame, similarity 0-1 (0.25), blend (0.1), spill (0.5), off} set_masks{clipId..., masks: [{shape rect|ellipse: x, y (top left), w, h as shares of the frame | path: points [[x,y],...] (a path changes shape with pathKeys: [{at: the clip's footage second, points}], each point moving straight to its place in the next shape; any point count, Rendrr matches them), feather: share of the short side, invert, mode add|subtract|intersect; a rect or ellipse moves with keys: [{at: the clip's footage second, x, y, w, h}] (a straight line between them), or follow: "face" (Rendrr measures the speaker's face over each V1 clip and makes the keys; the shape keeps its place against the face; without x, y, w, h an ellipse round the face), or follow: "object", object: a tracked object's id on that clip (track_object; the shape keeps its place against the object; without x, y, w, h a box round it)}], [] = none} set_effects{clipId..., effects: [{type blur|pixelate|sharpen (unsharp mask: 20 light, 50 clear, 100 strong)|darken (amount % darker)|vignette (darkens the edges; amount 35 is gentle)|glow (bright parts bloom)|grain (film grain)|rgbsplit (chromatic aberration)|shake (hand-held jitter)|mirror (left half reflected)|pin (corner pin: corners [[x,y] top left, top right, bottom left, bottom right] as shares of the frame; outside them what is under the clip shows), amount 1-100, area: a shape like a mask, keys and follow too (default the whole picture); a face blur that follows: blur in an ellipse follow "face"; a spotlight: darken 55 in an ellipse follow "face", invert true; a blurred logo or plate: blur in a rect follow "object"}]} track_object{clipId (V1 or b-roll), at: the clip's footage second (edit: true = edit second) where box{x, y (top left), w, h: shares of the clip's picture as fitted, before framing} is drawn tight round the object (get_frames to see it); label; Rendrr follows it through the clip on the server (forward and back from at) and says where it was lost (covered, out of frame: what follows it holds still there); id: track that object again from a new box or moment (what follows it moves with the new track) | remove: true with id (shapes keep its path as plain keys, pinned layers stop): then set_masks/set_effects follow "object" or pin_layer} pin_layer{clipId (text or graphic on V3), to{clipId, object}: it moves with the object, keeping where it is against it at the layer's first moment (keys made from the track, kept up to date when the edit changes); scale: true = it grows and shrinks with the object; off: true unpins it (its keys removed)} retouch_skin{clipIds|all (default every V1 clip), smooth (pores and texture; edges kept), blemishes (spots, marks, small dark patches), even (blotchy colour; lips keep theirs), brighten (lifts the skin): each 0-100, sent alone 35/40/35/0 = a natural retouch; values left out keep theirs; area: "face" (default: each clip's face, forehead to neck, measured by Rendrr) | "frame" | a shape; off: true removes it. The skin keeps its tone} stabilize{clipId|clipIds (V1 clips at any speed: ramps, reversed and freezes are smoothed through their speed changes; or b-roll)|all|video (default every V1 clip), smooth 0-100 (50; how much of the camera's movement is smoothed), off: true removes it: Warp Stabilizer for hand-held shots (get_footage's shaky stretches); the render zooms in a little to hide the edges} remove_background{clipIds (V1 clips or b-roll over the picture: its person cut out, the picture shows around them)|all|video (default every V1 clip): the person cut out of their background by an AI matte Rendrr makes of the footage (people, not objects; reversed clips too); what shows around them is set_background (colour, gradient, pattern, library video, blur) or b-roll laid behind with set_under; edge -20..20 (grow/shrink the cut, px at 1080p), soft 0-100 (feather, 20), invert: true (the person removed, the room kept); off: true puts the background back. The first render makes the matte (about half the footage's length on the server; kept and reused)} set_under{clipId (b-roll), under: true = behind V1} adjustment_layer{start, end (edit: true = edit seconds), grade: set_grade's fields, effects: as set_effects, label, masks: as set_masks (the layer works only inside them; a rect or ellipse moves with keys at: seconds from the layer's start; no follow), opacity 0-1 (its strength), fadeIn, fadeOut: seconds it ramps in and out; clipId: change one (grade and effects replaced; masks, opacity and fades left out are kept, null removes); delete_clip removes it: a V3 layer whose grade and effects go on everything under it over its time (footage, b-roll, graphics; text and captions stay as they are), as Premiere's} multicam{angles: [{videoId: another camera of the same take (a library video), offset?: seconds, the angle's moment at the main video's 0 (left out: Rendrr syncs it by timecode when both files carry one, the sound checking it, else by the sound; the result says how and how sure), name?, rotate?, framing?}] (added, or changed by videoId), audio: main (the main video's sound under every angle, default) | follow (each angle's own sound), remove: [videoId|name], off: true = none: a multicam for two-camera podcasts and interviews} switch_angle{angle: an angle's videoId or name | "main", clipId | clipIds | start, end | at (to the next change of angle, as cutting live in Premiere's multicam monitor); edit: true = edit seconds: which camera V1 shows there (clips split at the ends; the words, cuts and sound stay the main video's)} multicam_auto{cameras?: angle names or ids and "main" (default all), wide?: the camera when both speak, minShot? (s, default 2), start?, end? (footage s): cuts V1 to whoever speaks, from each camera's own sound (the person loudest on their mic gets the shot; Rendrr works the cuts out on the server)} set_blend{clipId | clipIds (b-roll on V2, graphics on V3), blend: normal|multiply|screen|overlay|soft-light|hard-light|add|lighten|darken|difference|exclusion|color-dodge|color-burn (as Premiere; screen and add for light leaks and glows, multiply and overlay for textures), opacity 0-1} set_export{hdr: keep (HDR footage stays HDR in the final) | sdr, resolution: 720p|1080p|4k, codec: h264|hevc, format: mp4|gif (up to 10 min: 15 fps and 640 px to a minute, 10 fps and 480 px to 3 min, 6 fps and 360 px beyond)|audio (sound only, .m4a)|wav|overlay (the graphics, text and captions on transparency, ProRes 4444, to lay over footage elsewhere), bitrate: Mbit/s (null = constant quality), fps: 24|25|30|50|60 (null = the footage's); every final also comes with SRT and WebVTT captions, and YouTube chapters from chapter marks} add_marks{marks: [{kind, start, end? (none: a moment), label?, note?, confidence?, videoId?}]: your notes on the footage, kept with the edit, never change the video; kind chapter with a label = a YouTube chapter (the final lists them as "0:00 Title" lines)} update_mark{id, label, note (null clears); yours: kind, start, end, confidence; Rendrr's: hidden} delete_mark{id | ids: yours go, Rendrr's are hidden in this edit}. Tracks: v1 the sequence (clips of any video, played in order with no gaps), v2 b-roll/zooms, v3 graphics, a1 dialogue (follows its V1 clip), a2 music, a3 sfx. Other tracks hang on the V1 clip under them and move with it. Times are kept to the millisecond (0.001 s): sound is cut exactly there, the picture on the nearest frame. Times: main-footage seconds where that footage first plays; V1 clip ops take that clip's own footage seconds; edit: true on any timed op = edit seconds.`;
const RULE_FIELDS = "cutSilencesOver (seconds or null), removeFillers, trimEdges, captions{on, look, wordsAtOnce, upper, maxLines, style: a full caption style (set_caption_style fields)}, zoom{mode: none|newSentence|interval|slowPush|count, scale, everySec, holdSec, count}, music{mood, gainDb}, sfxOnZoom";

/** ui: the tool opens the Rendrr app in the chat (an MCP App). app: only the app calls it, the AI does not see it. */
export type ToolDef = { name: string; title: string; description: string; input: z.ZodObject<z.ZodRawShape>; write?: boolean; long?: boolean; ui?: boolean; app?: boolean };

/** Where in the user's Google Drive a final goes (save_to_drive, render_final driveFolder). */
const DRIVE_FIELDS = {
  folder: z.string().max(500).optional().describe("Path from My Drive (\"Clients/BFS Health/Finals\"), a shared drive's name first for a shared drive, a Drive folder link, a folder id, or a folder's name. Default: My Drive"),
  createFolders: z.boolean().optional().describe("true: make the folders at the end of the path that are not there"),
  fileName: z.string().max(180).optional().describe("The file's name in Drive (default: \"<edit name> final v<version>.mp4\")"),
};

